/**
 * Deterministic 30-planet showcase catalog.
 *
 * Climate follows orbital distance (orbitT = i/29). Temperate worlds dominate
 * the habitable band; lava/scorched rock and ice sit only at the extremes.
 * Stable ids: cinder, azure, amber, glacier. Azure stays kind "ocean".
 */
import { cloneParams, paramsForPreset } from "../planet-texture/presets.js";
export const CATALOG_PLANET_COUNT = 30;
/** Golden-angle step so planets do not line up at t=0. */
const ORBIT_PHASE_STEP = 2.399;
export function climateZoneFromOrbitT(t) {
    const x = Number.isFinite(t) ? t : 0;
    if (x < 0.12)
        return "inner-hot";
    if (x < 0.72)
        return "habitable";
    if (x < 0.86)
        return "outer-cool";
    return "outer-ice";
}
/** Stable FNV-1a uint32. azure is pinned to 42. */
export function seedForCatalogId(id) {
    if (id === "azure")
        return 42;
    let h = 2166136261;
    for (let i = 0; i < id.length; i++) {
        h ^= id.charCodeAt(i);
        h = Math.imul(h, 16777619);
    }
    const seed = h >>> 0;
    return seed === 42 ? 43 : seed;
}
function lerp(a, b, t) {
    return a + (b - a) * t;
}
function orbitKinematics(i) {
    let orbitRadius;
    let orbitPeriodSec;
    if (i <= 3) {
        const u = i / 3;
        orbitRadius = lerp(6.2, 10.4, u);
        orbitPeriodSec = lerp(12, 20, u);
    }
    else if (i <= 20) {
        const u = (i - 4) / 16;
        orbitRadius = lerp(12.2, 28.5, u);
        orbitPeriodSec = lerp(24, 50, u);
    }
    else if (i <= 24) {
        const u = (i - 21) / 3;
        orbitRadius = lerp(31, 38, u);
        orbitPeriodSec = lerp(56, 72, u);
    }
    else {
        const u = Math.min(1, Math.max(0, (i - 25) / 4));
        orbitRadius = lerp(41, 56, u);
        orbitPeriodSec = lerp(84, 120, u);
    }
    return {
        orbitRadius,
        orbitPeriodSec,
        orbitPhase0: (i * ORBIT_PHASE_STEP) % (Math.PI * 2),
    };
}
function definePlanet(i, draft) {
    const orbitT = i / 29;
    const kin = orbitKinematics(i);
    return {
        ...draft,
        seed: draft.seed ?? seedForCatalogId(draft.id),
        orbitT,
        zone: climateZoneFromOrbitT(orbitT),
        orbitRadius: kin.orbitRadius,
        orbitPeriodSec: kin.orbitPeriodSec,
        orbitPhase0: kin.orbitPhase0,
    };
}
